        galleryMode = false;

        // Raid Boss contribution for channel visits
        if (typeof window._raidOnChannelVisit === 'function') window._raidOnChannelVisit(id);

        // Update SEO metrics (id, title, desc)
        if (typeof _updateSEO === 'function' && typeof CHANNELS !== 'undefined' && CHANNELS[id]) {
            var ch = CHANNELS[id];
            _updateSEO(id, ch.title || ch.name, ch.desc || '');
        }

        renderContent(id);

        // Scroll to search result if pending (retry at 200, 600, 1200ms for slow renders)
        if (window._searchScrollTarget && window._searchScrollTarget.channel === id) {
            var _scrollAttempts = 0;
            function _attemptScroll() {
                _scrollAttempts++;
                if (window._searchScrollTarget) {
                    var el = document.getElementById('msg-' + window._searchScrollTarget.msgIdx);
                    if (el || _scrollAttempts >= 3) {
                        if (typeof window._tryScrollToSearchResult === 'function') window._tryScrollToSearchResult();
                    } else {
                        setTimeout(_attemptScroll, _scrollAttempts * 400);
                    }
                }
            }
            setTimeout(_attemptScroll, 200);
        }

        // Trigger fade-in animation
        document.getElementById('hero').classList.add('fade-in');
        document.getElementById('msgs').classList.add('fade-in');

        // Setup load-more for list view
        window._currentMsgs = d.msgs;
        window._currentOffset = (typeof isMobile === 'function' && isMobile()) ? 20 : 50;
        window._currentLoadChannel = id;
        window.loadMoreMsgs = function() {
            // Guard against stale closure from rapid channel navigation
            if (window._currentLoadChannel !== currentChannelId) return;
            const offset = window._currentOffset;
            const msgs = window._currentMsgs;
            const btn = document.getElementById('loadMoreBtn');
            if (!btn) return;
            const nextBatch = msgs.slice(offset, offset + 50);
            let html = '';
            nextBatch.forEach((m, bi) => {
                html += '<div class="msg" id="msg-' + (offset + bi) + '">';
                if (m.text) { let t = m.text; let yt=[],tw=[]; t=t.replace(/(?:https?:\/\/)?(?:www\.)?youtube\.com\/watch\?v=([\w-]+)(?:[&?][^\s]*)?/g,function(m,id){yt.push(id);return '%%YT'+(yt.length-1)+'%%';}); t=t.replace(/(?:https?:\/\/)?youtu\.be\/([\w-]+)(?:\?[^\s]*)?/g,function(m,id){yt.push(id);return '%%YT'+(yt.length-1)+'%%';}); t=t.replace(/(?:https?:\/\/)?(?:twitter\.com|x\.com)\/([\w]+)\/status\/(\d+)(?:[^\s]*)?/g,function(m){var u=m.startsWith('http')?m:'https://'+m;tw.push(u);return '%%TW'+(tw.length-1)+'%%';}); t=t.replace(/(https?:\/\/[^\s<>"]+)/g,'<a class="msg-link" href="$1" target="_blank">$1</a>'); t=t.replace(/%%YT(\d+)%%/g,function(m,i){return '<div class="yt-embed"><iframe src="https://www.youtube-nocookie.com/embed/'+yt[parseInt(i)]+'" frameborder="0" allowfullscreen loading="lazy" decoding="async"></iframe></div>';}); t=t.replace(/%%TW(\d+)%%/g,function(m,i){var u=tw[parseInt(i)],tid='tw_'+Math.random().toString(36).substr(2,8),mob=typeof isMobile==='function'&&isMobile(),hm=u.match(/(?:twitter\.com|x\.com)\/([\w]+)\//),dh=hm?'@'+hm[1]:u.replace(/https?:\/\/(www\.)?/,'');return '<div class="tw-preview" id="'+tid+'" onclick="loadTweetEmbed(\''+tid+'\',\''+u+'\')"><div class="tw-preview-icon">𝕏</div><div class="tw-preview-content"><div class="tw-preview-url">'+dh+'</div><div class="tw-preview-hint">'+(mob?'▶ Tap to display tweet':'▶ Click to display tweet')+'</div></div><div class="tw-preview-arrow">→</div></div>';}); t=t.replace(/🟠 (.+)/g,'<span class="orange-glow">$1</span>'); html += '<div class="msg-text">' + t + '</div>'; }
                if (m.imgs) m.imgs.forEach(img => { if (m.link) { html += '<a href="' + m.link + '" target="_blank" style="display:block;"><img class="msg-img" src="' + img + '" loading="lazy" decoding="async" title="Click to open source"></a>'; } else { html += '<img class="msg-img" src="' + img + '" onclick="openImg(this.src)" loading="lazy" decoding="async">'; } });
                html += '</div>';
            });
            btn.insertAdjacentHTML('beforebegin', html);
            window._currentOffset = offset + 50;
            if (window._currentOffset >= msgs.length) { btn.remove(); window._scrollObserver && window._scrollObserver.disconnect(); }
            else { btn.textContent = 'Load more (' + (msgs.length - window._currentOffset) + ' remaining)'; }
        };
        
        // Auto-load more on scroll using IntersectionObserver (virtual scrolling lite)
        (function() {
            if (window._scrollObserver) { window._scrollObserver.disconnect(); window._scrollObserver = null; }
            if (!document.getElementById('loadMoreBtn')) return;
            window._scrollObserver = new IntersectionObserver(function(entries) {
                if (entries[0].isIntersecting && typeof window.loadMoreMsgs === 'function') {
                    window.loadMoreMsgs();
                }
            }, { root: null, rootMargin: '300px', threshold: 0 });
            var loadBtn = document.getElementById('loadMoreBtn');
            if (loadBtn) window._scrollObserver.observe(loadBtn);
        })();

